SH.importAdityaProjects = () => {
  const stored = JSON.parse(localStorage.getItem('sh_projects') || '[]');
  const deleted = new Set(
    JSON.parse(localStorage.getItem('sh_deleted_project_ids') || '[]').map(
      String
    )
  );
  const isAdityaImport = (project) =>
    project?.source === 'GitHub Aditya import' ||
    String(project?.id || '').startsWith('aditya-gh-');
  const filtered = stored.filter((project) => !isAdityaImport(project));
  const byId = new Map(
    filtered.map((project) => [String(project.id), project])
  );

  localStorage.setItem('sh_projects', JSON.stringify([...byId.values()]));

  const current = new Map(
    (SH.projects || [])
      .filter(
        (project) =>
          !isAdityaImport(project) && !deleted.has(String(project.id))
      )
      .map((project) => [String(project.id), project])
  );
  JSON.parse(localStorage.getItem('sh_projects') || '[]').forEach((project) => {
    if (!current.has(String(project.id)))
      current.set(String(project.id), project);
  });
  SH.projects = [...current.values()];
  return SH.projects;
};
